class TestWebhookRequestParam(TypedDict):
    type: NotRequired[Literal["delivery.created", "delivery.requires_action", "delivery.booked", "delivery.status_changed", "delivery.schedule_changed", "delivery.expiring", "delivery.cancelled", "wallet.funded", "wallet.low_balance", "invoice.issued", "invoice.paid", "invoice.overdue"] | str]
    """The event type to send. Defaults to `delivery.status_changed`. Any other value is `422 INVALID_REQUEST`."""


class AdvanceRequestParam(TypedDict):
    """Send `status` to move the delivery, or `deliver_by` with `reason` to simulate a schedule change."""
    status: NotRequired[DeliveryStatus]
    """`requires_action` waits on you (see `required_actions`). `scheduled` is booked and charged (or added to the invoice). `rider_assigned` means a rider has the pickup.

    `picked_up` is collected. `at_hub` is at a Reeds hub (via-hub deliveries), or at the collecting or the receiving hub of an inter-state delivery, which passes `at_hub` twice. `in_transit` is moving between those two hubs, on an inter-state delivery only.

    `out_for_delivery` is with the rider heading to the receiver. `delivered` and `cancelled` are final. `failed_attempt` means the rider could

    not deliver; Reeds will retry or contact you. `on_hold` is paused by Reeds (see `hold_reason`). There is no `ready` status.
    """
    hold_reason: NotRequired[str]
    """With `status` `on_hold`."""
    note: NotRequired[str]
    deliver_by: NotRequired[str]
    reason: NotRequired[str]
    """With `deliver_by`."""


